#include "SoundLibrary.h"
#include <juce_cryptography/juce_cryptography.h>
#include <algorithm>
#include <set>
namespace pulse {
using namespace juce;
String factorySoundId(const SynthPreset& p){return "factory-"+String((int)p.instrument)+"-"+p.name.toLowerCase().replaceCharacter(' ','-');}
const PersonalSound* findPersonalSound(const SoundLibrary& library,const String& id){for(const auto& row:library.personal)if(row.id==id)return &row;return nullptr;}
bool resolveLibrarySound(const SoundLibrary& library,const String& id,SynthPreset& output){if(auto* row=findPersonalSound(library,id)){output=row->sound;return true;}for(const auto& p:factorySynthPresets())if(factorySoundId(p)==id){output=p;return true;}return false;}
Result validateSoundLibrary(const SoundLibrary& library){
    if(library.personal.size()>maxPersonalSounds||library.favorites.size()>maxPersonalSounds+(int)factorySynthPresets().size())return Result::fail("The sound library supports 128 personal sounds and favorites for existing sounds.");
    std::set<String> ids,names,favorites;for(const auto& row:library.personal){if(!row.id.startsWith("user-")||row.id.length()>64||!row.id.containsOnly("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_")||!ids.insert(row.id).second)return Result::fail("Invalid or duplicate personal sound identity.");auto valid=validateSynthPreset(row.sound);if(valid.failed())return valid;
        if(row.sound.name!=row.sound.name.trim()||row.sound.category!=row.sound.category.trim())return Result::fail("Sound names and categories cannot have surrounding whitespace.");for(auto c:row.sound.name+row.sound.category)if(c<32||c==127)return Result::fail("Sound names and categories cannot contain control characters.");
        if(!names.insert(String((int)row.sound.instrument)+":"+row.sound.name.toLowerCase()).second)return Result::fail("A sound with that name already exists for this synth.");}
    for(const auto& id:library.favorites){SynthPreset ignored;if(!favorites.insert(id).second||!resolveLibrarySound(library,id,ignored))return Result::fail("Favorite references an unavailable or duplicate sound.");}return Result::ok();
}
var soundLibraryToJson(const SoundLibrary& library){auto* object=new DynamicObject();object->setProperty("schema",2);object->setProperty("application","Pulse Studio sound library");Array<var> personal,favorites;for(const auto& entry:library.personal){auto* row=new DynamicObject();row->setProperty("id",entry.id);row->setProperty("sound",synthPresetToJson(entry.sound));personal.add(var(row));}for(const auto& id:library.favorites)favorites.add(id);object->setProperty("personal",personal);object->setProperty("favorites",favorites);return var(object);}
Result soundLibraryFromJson(const var& json,SoundLibrary& output){if(!json.isObject()||!json["schema"].isInt()||((int)json["schema"]<1||(int)json["schema"]>2)||json["application"].toString()!="Pulse Studio sound library"||!json["personal"].isArray()||!json["favorites"].isArray())return Result::fail("Invalid or unsupported sound library.");auto& personal=*json["personal"].getArray();auto& favorites=*json["favorites"].getArray();if(personal.size()>maxPersonalSounds||favorites.size()>maxPersonalSounds+(int)factorySynthPresets().size())return Result::fail("Sound library capacity exceeded.");SoundLibrary next;
    for(const auto& row:personal){if(!row.isObject()||!row["id"].isString())return Result::fail("Invalid personal sound entry.");PersonalSound entry;entry.id=row["id"].toString();auto valid=synthPresetFromJson(row["sound"],entry.sound);if(valid.failed())return valid;next.personal.push_back(std::move(entry));}for(const auto& id:favorites){if(!id.isString())return Result::fail("Invalid sound favorite identity.");next.favorites.add(id.toString());}auto valid=validateSoundLibrary(next);if(valid.failed())return valid;output=std::move(next);return Result::ok();
}
String soundLibraryToken(const File& file){if(!file.exists())return "missing";if(!file.existsAsFile())return "not-file";if(file.getSize()>maxSoundLibraryBytes)return "oversized";return SHA256(file).toHexString();}
Result loadSoundLibrary(const File& file,SoundLibrary& output){if(!file.exists()){output={};return Result::ok();}if(!file.existsAsFile()||file.getSize()>maxSoundLibraryBytes)return Result::fail("Sound library must be a file no larger than 1 MiB.");var json;auto result=JSON::parse(file.loadFileAsString(),json);if(result.failed())return Result::fail("Cannot read sound library JSON: "+result.getErrorMessage());return soundLibraryFromJson(json,output);}
Result saveSoundLibrary(const File& file,const SoundLibrary& library,const String& expected){auto valid=validateSoundLibrary(library);if(valid.failed())return valid;auto token=soundLibraryToken(file);if(expected.isNotEmpty()&&token!=expected)return Result::fail("The sound library changed. Reopen Sounds before saving.");SoundLibrary current;valid=loadSoundLibrary(file,current);if(valid.failed())return valid;auto text=JSON::toString(soundLibraryToJson(library),false,22);if(text.getNumBytesAsUTF8()>maxSoundLibraryBytes)return Result::fail("The sound library exceeds 1 MiB.");valid=file.getParentDirectory().createDirectory();if(valid.failed())return valid;TemporaryFile temporary(file);if(!temporary.getFile().replaceWithText(text))return Result::fail("Could not write the sound library temporary file.");if(soundLibraryToken(file)!=token)return Result::fail("The sound library changed while saving. Reopen Sounds.");if(!temporary.overwriteTargetFileWithTemporary())return Result::fail("Could not commit the sound library. Existing contents are unchanged.");return Result::ok();}
namespace {
Result readForEdit(const File& file,SoundLibrary& library,String& token,const String& expected){token=soundLibraryToken(file);if(expected.isNotEmpty()&&expected!=token)return Result::fail("The sound library changed. Reopen Sounds.");return loadSoundLibrary(file,library);}
}
Result putPersonalSound(const File& file,const PersonalSound& sound,bool replace,const String& expected){SoundLibrary library;String token;auto result=readForEdit(file,library,token,expected);if(result.failed())return result;auto found=std::find_if(library.personal.begin(),library.personal.end(),[&](const PersonalSound& p){return p.id==sound.id;});if(replace){if(found==library.personal.end())return Result::fail("Personal sound was removed. Reopen Sounds.");*found=sound;}else{if(found!=library.personal.end())return Result::fail("Personal sound identity already exists.");library.personal.push_back(sound);}return saveSoundLibrary(file,library,token);}
Result removePersonalSound(const File& file,const String& id,const String& expected){SoundLibrary library;String token;auto result=readForEdit(file,library,token,expected);if(result.failed())return result;auto found=std::find_if(library.personal.begin(),library.personal.end(),[&](const PersonalSound& p){return p.id==id;});if(found==library.personal.end())return Result::fail("Personal sound was already removed.");library.personal.erase(found);library.favorites.removeString(id);return saveSoundLibrary(file,library,token);}
Result setSoundFavorite(const File& file,const String& id,bool favorite,const String& expected){SoundLibrary library;String token;auto result=readForEdit(file,library,token,expected);if(result.failed())return result;SynthPreset ignored;if(!resolveLibrarySound(library,id,ignored))return Result::fail("Sound is no longer available.");if(library.favorites.contains(id)==favorite)return Result::ok();if(favorite)library.favorites.add(id);else library.favorites.removeString(id);return saveSoundLibrary(file,library,token);}
}
